{() =>
                      setCart((current) => {
                        const next = { ...current };
                        const existing = next[line.product.id];
                        if (!existing) return next;
                        if (existing.quantity <= 1) delete next[line.product.id];
                        else next[line.product.id] = { ...existing, quantity: existing.quantity - 1 };
                        return next;
                      })
                    }

